$ErrorActionPreference='Stop'; $code=''; Get-CimInstance Win32_Process | Where-Object {$_.Name -eq 'powershell.exe' -and $_.CommandLine -like ('*'+$code+'*')} | ForEach-Object { 'Stopping this task launch wrapper PID '+$_.ProcessId; Stop-Process -Id $_.ProcessId -ErrorAction SilentlyContinue }; wpr.exe -status